// @name JSX: Calculator
// @background #000000
// @refresh 3600
// A calculator: a four-column grid of keys, active: lights the key under the
// finger, and the operator waiting for its second number stays lit.
const keys = ['C', '±', '%', '÷', '7', '8', '9', '×', '4', '5', '6', '−', '1', '2', '3', '+', '0', '.', '=']
const ops = {
  '+': (a, b) => a + b,
  '−': (a, b) => a - b,
  '×': (a, b) => a * b,
  '÷': (a, b) => a / b,
}

let display = '0'
let acc = null
let op = null
let fresh = true

const format = (n) => {
  if (!isFinite(n)) return 'Error'
  const s = String(parseFloat(n.toPrecision(9)))
  return s.length > 10 ? n.toExponential(3) : s
}

const press = (key) => {
  if (key >= '0' && key <= '9') {
    display = fresh || display === '0' ? key : display.length < 9 ? display + key : display
    fresh = false
  } else if (key === '.') {
    if (fresh) display = '0.'
    else if (!display.includes('.')) display += '.'
    fresh = false
  } else if (key === 'C') {
    display = '0'; acc = null; op = null; fresh = true
  } else if (key === '±') {
    if (display !== '0') display = display.startsWith('-') ? display.slice(1) : '-' + display
  } else if (key === '%') {
    display = format(parseFloat(display) / 100); fresh = true
  } else if (key === '=') {
    if (op && acc !== null) display = format(ops[op](acc, parseFloat(display)))
    acc = null; op = null; fresh = true
  } else {
    if (op && acc !== null && !fresh) display = format(ops[op](acc, parseFloat(display)))
    acc = parseFloat(display); op = key; fresh = true
  }
}

const tone = (key) => {
  if (key in ops || key === '=') {
    return key === op && fresh ? 'bg-white text-orange-500' : 'bg-orange-500 text-white active:bg-orange-300'
  }
  if (key === 'C' || key === '±' || key === '%') return 'bg-neutral-400 text-black active:bg-neutral-200'
  return 'bg-neutral-800 text-white active:bg-neutral-600'
}

export function get(app) {
  return (
    <div className="flex flex-col gap-3 p-4 bg-black">
      <div className="flex flex-col items-end justify-end h-20 px-3">
        <span className="text-lg text-neutral-500 h-6">{op && acc !== null ? `${format(acc)} ${op}` : ''}</span>
        <span className="text-5xl text-white truncate">{display}</span>
      </div>
      <div className="grid grid-cols-4 gap-2">
        {keys.map((key) => (
          <div className={`h-16 rounded-2xl flex items-center justify-center text-3xl ${key === '0' ? 'col-span-2' : ''} ${tone(key)}`}
            onClick={() => press(key)}>{key}</div>
        ))}
      </div>
    </div>
  )
}
